<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {request} from '../api/client'
import {submit,upload,recover} from '../api/diagnostic'
import {changesState} from '../api/diagnostic-risk'
import {eventUrl,saveCursor} from '../api/durable'
import {useModal} from '../api/modal'
import type {components} from '../api/schema'
type Session=components['schemas']['Session'];type Source=components['schemas']['Source'];type Preview=components['schemas']['Preview'];type Turn=components['schemas']['Turn'];type Original=components['schemas']['Original'];type Settings=components['schemas']['Settings'];type Segment=components['schemas']['Segment']
const props=defineProps<{initialId?:string}>();const emit=defineEmits<{settings:[]}>()
const session=ref<Session|null>(null),problem=ref(''),project=ref(''),environment=ref(''),paste=ref(''),fileList=ref<File[]>([]),fileInput=ref<HTMLInputElement|null>(null),fileKind=ref('log')
const sources=ref<Source[]>([]),selected=ref<string[]>([]),preview=ref<Preview|null>(null),turns=ref<Turn[]>([]),settings=ref<Settings|null>(null),busy=ref(false),working=ref(false),error=ref(''),progress=ref('')
const checkIndex=ref('');const previousCompleted=computed(()=>[...turns.value].reverse().find(t=>t.status==='completed'&&t.report));
const resultText=ref(''),note=ref(''),url=ref(''),related=ref<Session[]>([]),targets=ref<{id:string,name:string}[]>([]),dockerTarget=ref('')
const ranges=ref<Record<string,{start:number,end:number}>>({}),customRanges=ref(false)
const opened=ref<{title:string,text:string}|null>(null);useModal(opened)
const active=computed(()=>turns.value.find(t=>['queued','running'].includes(t.status)))
const orderedTurns=computed(()=>[...turns.value].reverse())
const sourceMap=computed(()=>Object.fromEntries(sources.value.map(s=>[s.id,s])))
const when=(v:string)=>new Date(v).toLocaleString('zh-CN',{hour12:false})
const state=(v:string)=>({queued:'等待分析',running:'正在分析',completed:'结果已保存',failed:'分析未完成',blocked:'已停止'}[v]??v)
function omitted(item:{total_lines:number,selected_ranges:number[][]}){const chunks:number[][]=[];let cursor=1;for(const [a,b] of [...item.selected_ranges].sort((x,y)=>x[0]!-y[0]!)){if(a!>cursor)chunks.push([cursor,a!-1]);cursor=Math.max(cursor,b!+1)}if(cursor<=item.total_lines)chunks.push([cursor,item.total_lines]);return chunks.map(([a,b])=>a===b?String(a):a+'–'+b).join('、')||'无'}
const kind=(v:string)=>({log:'用户日志',document:'项目资料',check_result:'用户检查结果',docker:'Docker采集',official_doc:'官方文档',history:'历史参考'}[v]??v)
let timer:ReturnType<typeof setTimeout>|undefined,stream:EventSource|null=null,disposed=false
function fail(e:unknown){error.value=e instanceof Error?e.message:String(e)}
watch(selected,()=>{preview.value=null},{deep:true});watch(ranges,()=>{if(customRanges.value)preview.value=null},{deep:true})
async function refresh(){if(!session.value)return;const [ss,tt]=await Promise.all([request<Source[]>('/diagnostic/sessions/'+session.value.id+'/sources'),request<Turn[]>('/diagnostic/sessions/'+session.value.id+'/turns')]);sources.value=ss;turns.value=tt;for(const s of ss)if(!ranges.value[s.id])ranges.value[s.id]={start:1,end:Math.min(s.summary.lines,30)}}
async function load(id:string){working.value=true;error.value='';preview.value=null;try{session.value=await request<Session>('/diagnostic/sessions/'+id);localStorage.setItem('opslens-diagnostic-session',id);problem.value=session.value.problem;project.value=session.value.project;environment.value=session.value.environment;await refresh();selected.value=sources.value.filter(s=>!sources.value.some(other=>other.name===s.name&&other.version>s.version)).map(s=>s.id);related.value=await request<Session[]>('/diagnostic/sessions/'+id+'/related');if(active.value)follow(active.value)}catch(e){fail(e)}finally{working.value=false}}
async function ensure(){if(session.value)return;session.value=await submit<Session>('/diagnostic/sessions',{problem:problem.value,project:project.value,environment:environment.value});localStorage.setItem('opslens-diagnostic-session',session.value.id);problem.value=session.value.problem}
function fresh(){stream?.close();if(timer)clearTimeout(timer);session.value=null;sources.value=[];turns.value=[];selected.value=[];preview.value=null;problem.value='';project.value='';environment.value='';paste.value='';resultText.value='';note.value='';url.value='';related.value=[];ranges.value={};customRanges.value=false;progress.value='';fileList.value=[];if(fileInput.value)fileInput.value.value='';busy.value=false;error.value='';localStorage.removeItem('opslens-diagnostic-session')}
function chooseFiles(e:Event){fileList.value=Array.from((e.target as HTMLInputElement).files??[])}
async function prepare(){working.value=true;error.value='';preview.value=null;try{
 if(fileList.value.length>4||fileList.value.some(f=>f.size>5*1024*1024))throw new Error('每次最多4个文件，单文件最多5MiB')
 await ensure()
 const newIds:string[]=[]
 if(paste.value.trim()){const s=await submit<Source>('/diagnostic/sessions/'+session.value!.id+'/sources',{name:'粘贴的报错',kind:'log',content:paste.value});newIds.push(s.id);paste.value=''}
 if(fileList.value.length){const ss=await upload<Source[]>('/diagnostic/sessions/'+session.value!.id+'/files',fileList.value,fileKind.value);newIds.push(...ss.map(s=>s.id));fileList.value=[];if(fileInput.value)fileInput.value.value=''}
 await refresh();if(newIds.length)selected.value=Array.from(new Set([...selected.value.filter(id=>!newIds.some(n=>sourceMap.value[n]?.name===sourceMap.value[id]?.name)),...newIds]))
 if(!selected.value.length)throw new Error('请粘贴报错、添加日志或选择已有资料')
 const body={source_ids:selected.value,ranges:customRanges.value?selected.value.map(id=>({source_id:id,start_line:ranges.value[id]?.start??1,end_line:ranges.value[id]?.end??1})):[]}
 preview.value=await submit<Preview>('/diagnostic/sessions/'+session.value!.id+'/previews',body)
 settings.value=await request<Settings>('/diagnostic/settings')
 related.value=await request<Session[]>('/diagnostic/sessions/'+session.value!.id+'/related')
}catch(e){fail(e)}finally{working.value=false}}
async function analyze(){if(!session.value||!preview.value)return;error.value='';working.value=true;try{const t=await submit<Turn>('/diagnostic/sessions/'+session.value.id+'/turns',{preview_id:preview.value.id,digest:preview.value.digest,confirm:true});await refresh();follow(t)}catch(e){fail(e)}finally{working.value=false}}
async function poll(){if(disposed||!session.value)return;try{await refresh();if(active.value)timer=setTimeout(poll,1000);else{busy.value=false;stream?.close();progress.value='分析记录已保存'}}catch(e){fail(e);timer=setTimeout(poll,1500)}}
function follow(t:Turn){stream?.close();if(timer)clearTimeout(timer);busy.value=['queued','running'].includes(t.status);if(!busy.value)return;stream=new EventSource(eventUrl('/diagnostic/turns/'+t.id+'/events'));stream.onmessage=e=>{saveCursor('/diagnostic/turns/'+t.id+'/events',e);try{progress.value=JSON.parse(e.data).payload?.message??''}catch{/* Poll remains authoritative. */}};stream.onerror=()=>{progress.value='正在重新连接，已保存请求不会重新发送'};void poll()}
async function checkResult(){if(!session.value||!resultText.value.trim())return;working.value=true;error.value='';try{const s=await submit<Source>('/diagnostic/sessions/'+session.value.id+'/sources',{name:'补充检查结果',kind:'check_result',content:resultText.value,...(checkIndex.value&&previousCompleted.value?{check_reference:{turn_id:previousCompleted.value.id,check_index:Number(checkIndex.value)}}:{})});resultText.value='';checkIndex.value='';await refresh();selected.value=Array.from(new Set([...selected.value,s.id]));preview.value=null;await prepare()}catch(e){fail(e)}finally{working.value=false}}
async function feedback(status:'open'|'solved'|'paused'){if(!session.value)return;working.value=true;try{session.value=await submit<Session>('/diagnostic/sessions/'+session.value.id+'/feedback',{status,note:note.value});note.value=''}catch(e){fail(e)}finally{working.value=false}}
async function openSource(id:string,start=1,end?:number){if(!session.value)return;try{const s=await request<Original>('/diagnostic/sessions/'+session.value.id+'/sources/'+id);const lines=s.content.split('\n');const last=Math.min(end??start+119,lines.length);opened.value={title:s.name+' v'+s.version+' · '+kind(s.kind),text:lines.slice(start-1,last).map((line,i)=>String(start+i).padStart(5)+'  '+line).join('\n')+(last<lines.length?'\n\n（尚有其他行，可用行范围选取或导出完整脱敏记录）':'')}}catch(e){fail(e)}}
async function citation(turn:Turn,id:string){try{const p=await request<Preview>('/diagnostic/sessions/'+turn.session_id+'/previews/'+turn.preview_id);const s=p.segments.find(r=>r.id===id);if(s)await openSource(s.source_id,s.start_line,s.end_line)}catch(e){fail(e)}}
async function doc(){working.value=true;error.value='';try{await ensure();const s=await submit<Source>('/diagnostic/sessions/'+session.value!.id+'/official-document',{url:url.value});await refresh();selected.value=[...selected.value,s.id];url.value=''}catch(e){fail(e)}finally{working.value=false}}
async function history(id:string){working.value=true;try{if(!session.value)return;const s=await submit<Source>('/diagnostic/sessions/'+session.value.id+'/history-reference',{reference_session_id:id});await refresh();selected.value=[...selected.value,s.id]}catch(e){fail(e)}finally{working.value=false}}
async function docker(){working.value=true;error.value='';try{await ensure();const s=await submit<Source>('/diagnostic/sessions/'+session.value!.id+'/docker',{target_id:dockerTarget.value});await refresh();selected.value=[...selected.value,s.id]}catch(e){fail(e)}finally{working.value=false}}
onMounted(async()=>{try{const recovered=await recover();const restored=recovered.find(r=>r.kind==='session')?.value as Session|undefined;settings.value=await request<Settings>('/diagnostic/settings');targets.value=await request('/external-targets');dockerTarget.value=targets.value[0]?.id??'';const id=props.initialId??restored?.id??localStorage.getItem('opslens-diagnostic-session');if(id)await load(id)}catch(e){fail(e)}})
onUnmounted(()=>{disposed=true;stream?.close();if(timer)clearTimeout(timer)})
</script>
<template><div class="diagnostic">
 <div class="alert" role="alert" v-if="error">{{error}}</div><p v-if="progress" class="muted" role="status">{{progress}}</p>
 <article v-for="(t,index) in orderedTurns" :key="t.id" class="panel diag-report"><details :open="index===0"><summary class="heading"><h2>{{index===0?'最新分析':'此前分析'}}</h2><span class="pill">{{state(t.status)}}</span></summary><p class="muted">{{when(t.created_at)}} · 结论仅针对提供的资料，候选原因尚待验证</p><p v-if="t.error" class="inline-error">{{t.error}}</p><template v-if="t.report"><h3>{{t.report.summary}}</h3><h3 v-if="(t.report.facts??[]).length">已观察到的事实</h3><div v-for="(f,i) in t.report.facts" :key="i" class="diag-fact"><p>{{f.text}}</p><button v-for="(q,j) in f.citations" :key="j" class="text-button" @click="citation(t,q.id)">“{{q.quote}}” · 查看原文 ↗</button></div><h3 v-if="(t.report.candidate_causes??[]).length">候选原因 · 尚未验证</h3><div v-for="(c,i) in t.report.candidate_causes" :key="i"><strong>{{c.title}}</strong><p>{{c.reason}}</p><p class="muted" v-if="!(c.citations??[]).length">基于一般知识的推测，尚缺来源依据</p><button v-for="q in c.citations" :key="q.id+q.quote" class="text-button" @click="citation(t,q.id)">“{{q.quote}}” · 查看来源 ↗</button></div><h3 v-if="(t.report.next_checks??[]).length">下一步检查</h3><div v-for="(x,i) in t.report.next_checks" :key="i" class="diag-step"><strong>{{i+1}}. {{x.purpose}}</strong><p>{{x.operation}}</p><p class="muted">预期：{{x.expected}}</p><span class="pill" :class="changesState(x)?'amber':''">{{changesState(x)?'可能改变状态，请先审阅':'检查步骤'}}</span></div><h3 v-if="(t.report.missing_information??[]).length">还需要你补充</h3><ul><li v-for="(q,i) in t.report.missing_information" :key="i">{{q}}</li></ul><details><summary>分析记录</summary><p>模型 {{t.metrics.model}} · 请求 {{t.metrics.model_calls}} 次 · 未知用量 {{t.metrics.usage_unknown}} 次</p></details></template></details></article>
 <article v-if="session" class="panel diag-followup"><h2>补充检查结果</h2><p class="muted">按建议检查后，将输出或现象补充到这次排查；不会覆盖旧资料和分析。</p><label v-if="previousCompleted?.report?.next_checks?.length">关联检查（可选）<select aria-label="关联上一轮检查" v-model="checkIndex" :disabled="busy||working"><option value="">未关联</option><option v-for="(x,i) in previousCompleted.report.next_checks" :key="i" :value="String(i+1)">第{{i+1}}项：{{x.purpose}}</option></select></label><textarea aria-label="补充检查结果" v-model="resultText" rows="4" :disabled="busy||working"></textarea><button class="secondary" :disabled="busy||working||!resultText.trim()" @click="checkResult">保存并预览下一轮</button><details class="diag-feedback"><summary>结果与记录导出</summary><p>当前状态：{{session.status==='solved'?'用户反馈已解决（不是自动根因验证）':session.status==='paused'?'用户暂停':'仍在排查'}}</p><textarea aria-label="解决反馈说明" v-model="note" rows="2" placeholder="记录检查过程或解决方式，可留空"></textarea><div class="diag-actions"><button class="secondary" :disabled="busy||working" @click="feedback('solved')">标记已解决</button><button class="secondary" :disabled="busy||working" @click="feedback('open')">仍未解决</button><button class="secondary" :disabled="busy||working" @click="feedback('paused')">暂停</button><a class="text-button" :href="'/api/v1/diagnostic/sessions/'+session.id+'/export'">导出Markdown</a></div></details></article>
 <article class="panel"><div class="heading"><h2>{{session?'继续这次排查':'遇到了什么问题？'}}</h2><button v-if="session" class="secondary" :disabled="busy||working" @click="fresh">新排查</button></div>
 <label for="diag-problem">问题描述（可选）</label><textarea id="diag-problem" v-model="problem" maxlength="4000" rows="2" :readonly="!!session" placeholder="例如：部署后接口返回500，或服务启动时连接数据库失败。"></textarea>
 <details v-if="!session"><summary>项目与环境（可选）</summary><label>项目名称<input v-model="project" maxlength="100"></label><label>环境说明<input v-model="environment" maxlength="1000" placeholder="系统、框架版本或部署方式；不知道可留空"></label></details>
 <label for="diag-paste">粘贴报错或日志</label><textarea id="diag-paste" v-model="paste" rows="6" :disabled="busy||working" placeholder="支持堆栈、普通日志或JSON日志。先在本机整理、脱敏，不会立即发送模型。"></textarea>
 <div class="diag-upload"><label for="diag-files">添加文本文件（最多4个，每个5MiB）</label><input id="diag-files" ref="fileInput" type="file" multiple accept=".log,.txt,.json,.jsonl" :disabled="busy||working" @change="chooseFiles"><select aria-label="文件用途" v-model="fileKind"><option value="log">日志与报错</option><option value="document">项目资料</option></select></div>
 <button class="primary" :disabled="busy||working||(!paste.trim()&&!fileList.length&&!selected.length)" @click="prepare">{{working?'正在处理…':'整理并预览'}}</button><p class="muted">不需要登记项目。这里只读文本，完整脱敏资料保留在本机；不会执行文件或修复命令。</p>
 </article>
 <article class="panel" v-if="sources.length"><div class="heading"><h2>本机资料与线索</h2><span class="muted">{{sources.length}} 份</span></div><div v-for="s in sources" :key="s.id" class="diag-source"><label class="diag-check"><input type="checkbox" v-model="selected" :value="s.id" :disabled="busy||working"><strong>{{s.name}} v{{s.version}}</strong> · {{kind(s.kind)}} · {{s.summary.lines}} 行</label><p class="muted">录入时间：{{when(s.created_at)}}<span v-if="s.provenance.fetched_at"> · 正文获取时间：{{when(String(s.provenance.fetched_at))}}</span><span v-if="s.provenance.captured_at"> · 采集时间：{{when(String(s.provenance.captured_at))}}</span><span v-if="s.provenance.url"> · 来源：{{s.provenance.url}}</span></p><p class="muted">{{s.summary.message}}<span v-if="s.kind==='history'"> · 不能证明当前问题相同</span></p><ul class="diag-clues"><li v-for="g in s.summary.groups.slice(0,5)" :key="g.signature"><button class="text-button" @click="openSource(s.id,Math.max(1,g.last_line-4),Math.min(s.summary.lines,g.last_line+15))">{{g.signature}} · {{g.count}} 次 · 首行{{g.first_line}}／末行{{g.last_line}}</button></li></ul><button class="text-button" @click="openSource(s.id)">查看脱敏原文</button><div v-if="customRanges" class="diag-range"><label>开始行<input type="number" min="1" v-model.number="ranges[s.id]!.start"></label><label>结束行<input type="number" min="1" :max="s.summary.lines" v-model.number="ranges[s.id]!.end"></label></div></div><label class="diag-check"><input type="checkbox" v-model="customRanges" :disabled="busy||working" @change="preview=null">手动选择行范围</label><button class="secondary" :disabled="busy||working||!selected.length" @click="prepare">更新预览范围</button></article>
 <article class="panel diag-preview" v-if="preview"><div class="heading"><h2>将发送的资料</h2><span class="pill">{{Number(preview.coverage.model_input_bytes)}} / 32768 字节</span></div><p class="muted">原资料 {{Number(preview.coverage.total_source_bytes)}} 字节，选中正文 {{Number(preview.coverage.selected_text_bytes)}} 字节。未选中部分保留在本机，不会发送。</p><p class="muted" v-for="s in (preview.coverage.sources as {id:string,name:string,total_lines:number,selected_ranges:number[][]}[])" :key="s.id">{{s.name}} · 共{{s.total_lines}}行 · 省略行：{{omitted(s)}}</p><details v-for="p in preview.segments" :key="p.id"><summary>{{p.name}} · {{p.start_line}}–{{p.end_line}}行 · {{kind(p.kind)}}<span v-if="p.omitted_characters"> · 本段另省略{{p.omitted_characters}}字符</span></summary><pre>{{p.content}}</pre></details><details v-if="preview.continuation?.previous_turn_id"><summary>续轮上下文 · 用户结果尚未核验</summary><p>上一轮摘要：{{preview.continuation.previous_hypothesis}}</p><div v-for="(x,i) in (preview.continuation.previous_checks as {purpose:string,operation:string,expected:string}[])" :key="i"><strong>第{{i+1}}项：{{x.purpose}}</strong><p>{{x.operation}}；预期：{{x.expected}}</p></div><p v-for="r in (preview.continuation.provided_results as {source_id:string,check_reference?:{check_index:number},status:string}[])" :key="r.source_id">{{sourceMap[r.source_id]?.name}}：{{r.check_reference?'关联第'+r.check_reference.check_index+'项':'未关联检查'}} · {{r.status}}</p><p>只发送仍选中的原文；此前未选中的资料不加入本轮。</p></details><p v-if="settings" class="muted">{{settings.settings.mode==='free'?'百炼免费模式':settings.settings.base_url}} · {{settings.settings.model}}。确认分析将发送问题描述、环境、选中片段及下方续轮上下文。</p><p v-if="!settings?.available" class="inline-error">{{settings?.reason}} <button class="text-button" @click="emit('settings')">打开设置 →</button></p><button class="primary" :disabled="busy||working||!settings?.available||session?.status!=='open'" @click="analyze">确认选中资料并分析</button></article>
 <details class="panel"><summary>补充官方文档、历史参考或Docker资料（可选）</summary><p class="muted">优先使用日志；文档解释机制，历史记录不能证明当前状态。联网只读取你选择的官方链接，不搜索或发送日志。</p><label for="diag-link">官方文档链接</label><input id="diag-link" v-model="url" placeholder="https://官方域名/文档路径"><button class="secondary" :disabled="busy||working||!url.trim()" @click="doc">读取文档正文</button><div v-if="sources.some(s=>s.summary.links.length)"><p>日志中发现的链接（点击仅填写地址）：</p><button v-for="link in [...new Set(sources.flatMap(s=>s.summary.links))]" :key="link" class="text-button" @click="url=link">{{link}}</button></div><h3 v-if="related.length">类似历史排查</h3><div v-for="s in related" :key="s.id"><p>{{s.problem||s.project||'历史排查'}} · {{s.status==='solved'?'用户反馈已解决':'未确认解决'}}</p><button class="secondary" :disabled="busy||working" @click="history(s.id)">作为历史参考添加</button></div><label for="diag-docker">已有Docker只读接入</label><select id="diag-docker" v-model="dockerTarget"><option v-for="t in targets" :key="t.id" :value="t.id">{{t.name}}</option></select><button class="secondary" :disabled="busy||working||!dockerTarget" @click="docker">只读采集并添加</button></details>
 <div v-if="opened" class="modal-backdrop" @click.self="opened=null"><section class="evidence-modal" role="dialog" aria-modal="true" aria-labelledby="diag-source-title"><div class="heading"><h2 id="diag-source-title">{{opened.title}}</h2><button class="close" aria-label="关闭原文" @click="opened=null">×</button></div><pre>{{opened.text}}</pre></section></div>
</div></template>
